<label for="{{ $x }}-name">{{ __('Name') }}</label><input id="{{ $x }}-name" name="name" value="{{ $s?->name }}" required maxlength="200">
<label for="{{ $x }}-scope">{{ __('Which files') }}</label><select id="{{ $x }}-scope" name="scope">@foreach($scopes as $o)<option value="{{ $o->notation }}" @selected(($s?->scope->notation ?? 'all') === $o->notation)>{{ $o->label($lang) }}</option>@endforeach</select>
<label for="{{ $x }}-repository">{{ __('Repository, for a repository\'s files') }}</label><select id="{{ $x }}-repository" name="repository_id"><option value=""></option>@foreach($repositories as $r)<option value="{{ $r->id }}" @selected($s?->repository_id === $r->id)>{{ \App\Relations\EntityKinds::label($r) }}</option>@endforeach</select>
<label for="{{ $x }}-record">{{ __('Record, for a record and what is inside it (its UUID)') }}</label><input id="{{ $x }}-record" name="record_resource_id" value="{{ $s?->record_resource_id }}" maxlength="36">
<label for="{{ $x }}-frequency">{{ __('How often') }}</label><select id="{{ $x }}-frequency" name="frequency">@foreach($frequencies as $o)<option value="{{ $o->notation }}" @selected(($s?->frequency->notation ?? 'weekly') === $o->notation)>{{ $o->label($lang) }}</option>@endforeach</select>
<label for="{{ $x }}-stale">{{ __('Only files not checked for this many days (0: every file)') }}</label><input id="{{ $x }}-stale" name="stale_days" value="{{ $s?->stale_days ?? 0 }}" inputmode="numeric">
<label for="{{ $x }}-batch">{{ __('At most this many files a run') }}</label><input id="{{ $x }}-batch" name="batch_size" value="{{ $s?->batch_size ?? 500 }}" inputmode="numeric">
<label for="{{ $x }}-minutes">{{ __('At most this many minutes a run') }}</label><input id="{{ $x }}-minutes" name="max_runtime_minutes" value="{{ $s?->max_runtime_minutes ?? 60 }}" inputmode="numeric">
